# oracle-ledger-ffmpeg.ps1 — generate a per-shown-frame visible-MD5 ledger
# using ffmpeg's NATIVE VP9 decoder (NOT libvpx-vp9), to be cross-checked
# against the libvpx vpxdec ledger generated by encode-corpus.ps1.
#
# Together they form the "two independent decoders must agree on the
# bitstream" foundation of the multi-oracle conformance test: any future
# bug we suspect is in our decoder can be triangulated automatically — if
# both oracles agree on the decoded output and ours doesn't, the bug is
# unambiguously ours (Wave O — added after foreman_c440.ivf surfaced a
# pre-existing rvp9dec keyframe parser desync; vpxdec + ffmpeg both agreed
# on that bitstream, confirming the bug was on our side).
#
# Writes <vector>.ffmpeg.md5 alongside the existing <vector>.md5.
# Filename column matches the sibling vpxdec ledger (parses the first
# line to extract the stem prefix) so `diff <vector>.md5 <vector>.ffmpeg.md5`
# is empty when the oracles agree byte-for-byte.
#
# Usage:
#   pwsh scripts/oracle-ledger-ffmpeg.ps1 -Vector tests/corpus/profile1/foreman_c440.ivf [-Verify]
#
# -Verify asserts hash-column equality vs the sibling vpxdec ledger and
# exits 1 on disagreement.

param(
    [Parameter(Mandatory = $true)] [string] $Vector,
    [switch] $Verify
)
$ErrorActionPreference = 'Stop'

if (-not (Test-Path $Vector)) { throw "vector not found: $Vector" }
$abs = (Resolve-Path $Vector).Path
$vpxLedger = "$abs.md5"
$outLedger = "$abs.ffmpeg.md5"

# Probe pix_fmt + dims.
$probe = & ffprobe -v error -select_streams v:0 -show_entries stream=width,height,pix_fmt -of default=nw=1 $abs
$probeMap = @{}
foreach ($l in $probe) {
    $kv = $l -split '=', 2
    if ($kv.Count -eq 2) { $probeMap[$kv[0]] = $kv[1] }
}
$w  = [int]$probeMap['width']
$ht = [int]$probeMap['height']
$pf = $probeMap['pix_fmt']

# Native-chroma sizing matching md5_of_yv12_visible (Y at WxH, then U,V
# at chroma dims). Visible-dim rounding follows libvpx: (crop + ss) >> ss.
# All our current vectors have even W and H, so plain >>1 is exact.
switch ($pf) {
    'yuv420p' { $cw = $w/2; $ch = $ht/2; $ext = 'i420' }
    'yuv422p' { $cw = $w/2; $ch = $ht;   $ext = 'i422' }
    'yuv440p' { $cw = $w;   $ch = $ht/2; $ext = 'i440' }
    'yuv444p' { $cw = $w;   $ch = $ht;   $ext = 'i444' }
    default   { throw "unsupported pix_fmt for VP9 oracle: $pf" }
}
$framelen = $w*$ht + 2 * $cw * $ch

# Derive the filename stem from the sibling vpxdec ledger's first line, so
# the two ledgers can be diff-equal when the oracles agree. Falls back to
# the vector's bare filename if no vpxdec ledger is present.
$stem = (Split-Path -Leaf $abs)
if (Test-Path $vpxLedger) {
    $first = (Get-Content $vpxLedger -TotalCount 1)
    if ($first -match '^[0-9a-fA-F]{32}\s+(.+?)-\d+x\d+-\d+\.i\d{3}\s*$') {
        $stem = $Matches[1]
    }
}

# Decode to raw via ffmpeg's NATIVE vp9 decoder (NOT libvpx-vp9 — we need
# an independent implementation for genuine triangulation).
$work = Join-Path $env:TEMP ("oracle-ffmpeg-" + [guid]::NewGuid())
New-Item -ItemType Directory -Force $work | Out-Null
try {
    $raw = Join-Path $work 'all.yuv'
    & ffmpeg -y -hide_banner -loglevel error -c:v vp9 -i $abs -pix_fmt $pf -f rawvideo $raw
    $bytes = (Get-Item $raw).Length
    if ($bytes % $framelen -ne 0) { throw "raw $bytes not divisible by framelen $framelen" }
    $frames = [int]($bytes / $framelen)

    $ledger = New-Object System.Collections.Generic.List[string]
    $fs = [System.IO.File]::OpenRead($raw)
    try {
        $buf = New-Object byte[] $framelen
        for ($i = 1; $i -le $frames; $i++) {
            [void]$fs.Read($buf, 0, $framelen)
            $m = [System.Security.Cryptography.MD5]::Create()
            $hash = ($m.ComputeHash($buf) | ForEach-Object { $_.ToString('x2') }) -join ''
            $m.Dispose()
            $name = "{0}-{1}x{2}-{3:D4}.{4}" -f $stem, $w, $ht, $i, $ext
            $ledger.Add("$hash  $name")
        }
    } finally { $fs.Dispose() }

    Set-Content -Path $outLedger -Value $ledger -Encoding ascii
    Write-Output "wrote $outLedger ($($ledger.Count) frames, pix_fmt=$pf, ${w}x${ht})"

    if ($Verify) {
        if (-not (Test-Path $vpxLedger)) { throw "verify failed: no vpxdec ledger at $vpxLedger" }
        $vpx = Get-Content $vpxLedger
        $ff  = Get-Content $outLedger
        if ($vpx.Count -ne $ff.Count) {
            throw "ledger length mismatch: vpxdec=$($vpx.Count) ffmpeg=$($ff.Count)"
        }
        $diff = 0
        for ($i = 0; $i -lt $vpx.Count; $i++) {
            if ($vpx[$i].Substring(0,32) -ne $ff[$i].Substring(0,32)) { $diff++ }
        }
        if ($diff -ne 0) {
            Write-Error "ORACLE DISAGREEMENT: $diff / $($vpx.Count) frames differ between vpxdec and ffmpeg on $abs"
            exit 1
        }
        Write-Output "verified: vpxdec and ffmpeg agree on all $($vpx.Count) frames"
    }
}
finally {
    Remove-Item -Recurse -Force $work -ErrorAction SilentlyContinue
}
